<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Category; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\View\View;
class CategoryController extends Controller { public function index(): View { return view('admin.categories.index',['categories'=>Category::with('parent')->orderBy('parent_id')->orderBy('name')->get()]); } public function create(): View { return view('admin.categories.form',['category'=>new Category,'parents'=>Category::with('parent')->get()]); } public function store(Request $r): RedirectResponse { Category::create($this->data($r)); return to_route('admin.categories.index')->with('success','Collection created.'); } public function edit(Category $category): View { return view('admin.categories.form',['category'=>$category,'parents'=>Category::with('parent')->whereKeyNot($category->id)->get()]); } public function update(Request $r,Category $category): RedirectResponse { $category->update($this->data($r,$category)); return to_route('admin.categories.index')->with('success','Collection updated.'); } public function destroy(Category $category): RedirectResponse { abort_if($category->children()->exists() || $category->products()->exists(),422,'Move child collections and products before deletion.'); $category->delete(); return back()->with('success','Collection removed.'); } private function data(Request $r,?Category $existing=null): array { $d=$r->validate(['name'=>'required|string|max:100','parent_id'=>'nullable|exists:categories,id','image'=>'nullable|url|max:500','description'=>'nullable|string|max:500']); $parent=$d['parent_id']?Category::find($d['parent_id']):null; abort_if($parent && $parent->level()>=3,422,'Only three category levels are allowed.'); $d['slug']=Str::slug($d['name']).($existing?'':'-'.Str::lower(Str::random(4))); return $d; } }
